    @Test
    public void description_names_are_safe_deterministic_and_keep_a_late_word() throws IOException {
        File folder = temporaryFolder.resolve("description").toFile();
        String description = repeat("prefix ", 50) + "lateMeaningfulRule";
        ArchRule rule = rule(description);

        TextFileBasedViolationStore first = new TextFileBasedViolationStore();
        first.initialize(properties(folder, "default.fileNames", "description", "default.allowStoreCreation", "true"));
        first.save(rule, ImmutableList.of("violation"));
        String firstName = readProperties(folder).getProperty(description);

        TextFileBasedViolationStore second = new TextFileBasedViolationStore();
        second.initialize(properties(folder, "default.fileNames", "description"));
        second.save(rule("another rule"), ImmutableList.of("violation"));
        String secondName = readProperties(folder).getProperty("another rule");

        assertThat(firstName).contains("lateMeaningfulRule").matches("[A-Za-z0-9_-]+").hasSizeLessThanOrEqualTo(200).isNotEqualTo("stored.rules");
        assertThat(secondName).isNotEqualTo(firstName);
    }

