        index.setProperty("misplaced", "old-file");
        index.setProperty("kept", "kept");
        storeProperties(folder, index);
        write(folder, "empty-file", "\r\n\r");
        write(folder, "old-file", "violation\n");
        write(folder, "kept", "violation\n");
        write(folder, "unowned", "unowned\n");

        TextFileBasedViolationStore store = new TextFileBasedViolationStore(description -> description);
        store.initialize(properties(folder,
                "default.integrity", "repair",
                "default.allowStoreUpdate", "true"));

        Properties repaired = readProperties(folder);
        assertThat(repaired).doesNotContainKeys("broken", "empty").containsEntry("misplaced", "misplaced").containsEntry("kept", "kept");
        assertThat(new File(folder, "missing")).doesNotExist();
        assertThat(new File(folder, "empty-file")).doesNotExist();
        assertThat(new File(folder, "old-file")).doesNotExist();
        assertThat(new File(folder, "misplaced")).hasContent("violation\n");
        assertThat(new File(folder, "unowned")).exists();
