 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * By default, the layout within the configured store folder will look like:
 * <pre><code>
 * storeFolder
 *   |-- stored.rules (the index file of all stored rules)
 *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file named randomly by UUID and referenced from stored.rules)
 *   |-- ... (more rule violation files for every rule that has been stored so far)
 * </code></pre>
 *
 * <p>This {@link ViolationStore} can be configured through the following properties:</p>
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=random|description|... # how new violation files are named
 * default.integrity=repair|fail|ignore   # how the index and its files are checked
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("[A-Za-z0-9]{4,}");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String RANDOM_FILE_NAMES = "random";
    private static final String DESCRIPTION_FILE_NAMES = "description";
    private static final String REPAIR_INTEGRITY = "repair";
    private static final String FAIL_INTEGRITY = "fail";
    private static final String IGNORE_INTEGRITY = "ignore";
    private static final int MAX_FILE_NAME_LENGTH = 200;

    /* The object is both the index cache and the per-store-folder lock. */
    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean strategyWasProvidedToConstructor;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private File storeFolder;
    private FileSyncedProperties storedRules;
    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private String integrityMode;
    private boolean randomFileNames;

    /**
     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = new RandomRuleViolationFileNameStrategy();
        strategyWasProvidedToConstructor = false;
    }

    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new IllegalArgumentException("ruleViolationFileNameStrategy must not be null");
        }
        constructorStrategy = ruleViolationFileNameStrategy;
        strategyWasProvidedToConstructor = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = parseIntegrityMode(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        configureFileNameStrategy(properties);

        if (REPAIR_INTEGRITY.equals(integrityMode) && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Repairing violation store integrity is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        File storedRulesFile = getStoredRulesFile();
        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());

        FileSyncedProperties sharedRules = getOrCreateStoredRules(storedRulesFile);
        synchronized (sharedRules) {
            prepareStoreFolderAndIndex(storedRulesFile);
            sharedRules.reload();
            storedRules = sharedRules;
            if (!IGNORE_INTEGRITY.equals(integrityMode)) {
                IntegrityAnalysis analysis = analyzeIntegrity();
                if (FAIL_INTEGRITY.equals(integrityMode) && analysis.hasProblems()) {
                    throw new StoreInitializationFailedException(analysis.failureMessage(storedRulesFile));
                }
                if (REPAIR_INTEGRITY.equals(integrityMode)) {
                    repair(analysis);
                }
            }
        }
    }

    private String parseIntegrityMode(String configuredMode) {
        if (REPAIR_INTEGRITY.equals(configuredMode) || FAIL_INTEGRITY.equals(configuredMode) || IGNORE_INTEGRITY.equals(configuredMode)) {
            return configuredMode;
        }
        throw new StoreInitializationFailedException(String.format(
                "Invalid %s '%s' (accepted values are repair, fail and ignore)", INTEGRITY_PROPERTY_NAME, configuredMode));
    }

    private void configureFileNameStrategy(Properties properties) {
        if (strategyWasProvidedToConstructor) {
            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor", FILE_NAMES_PROPERTY_NAME));
            }
            ruleViolationFileNameStrategy = constructorStrategy;
            randomFileNames = false;
            return;
        }

        if (!properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
            ruleViolationFileNameStrategy = constructorStrategy;
            randomFileNames = true;
            return;
        }

        String configuredFileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
        if (RANDOM_FILE_NAMES.equals(configuredFileNames)) {
            ruleViolationFileNameStrategy = constructorStrategy;
            randomFileNames = true;
        } else if (DESCRIPTION_FILE_NAMES.equals(configuredFileNames)) {
            ruleViolationFileNameStrategy = new DescriptionRuleViolationFileNameStrategy();
            randomFileNames = false;
        } else {
            ruleViolationFileNameStrategy = instantiateStrategy(configuredFileNames);
            randomFileNames = false;
        }
    }

    @SuppressWarnings("unchecked")
    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> strategyClass = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
            Constructor<?> constructor = strategyClass.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured through %s='%s'; it must be a public RuleViolationFileNameStrategy with a public no-argument constructor",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
        try {
            String canonicalPath = storedRulesFile.getCanonicalPath();
            return STORED_RULES_BY_PATH.computeIfAbsent(canonicalPath, path -> new FileSyncedProperties(storedRulesFile));
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private File getStoredRulesFile() {
        return new File(storeFolder, STORED_RULES_FILE_NAME);
    }

    private void prepareStoreFolderAndIndex(File storedRulesFile) {
        Path folderPath = storeFolder.toPath();
        boolean folderExists = Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS);
        if (!folderExists) {
            if (FAIL_INTEGRITY.equals(integrityMode)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot initialize violation store in fail mode because the store folder does not exist: %s", storeFolder.getAbsolutePath()));
            }
            if (!storeCreationAllowed) {
                throwStoreCreationDisabled();
            }
            if (!storeFolder.mkdirs() && !storeFolder.isDirectory()) {
                throw new StoreInitializationFailedException(String.format("Cannot create violation store folder %s", storeFolder.getAbsolutePath()));
            }
        }
        if (!storeFolder.isDirectory()) {
            throw new StoreInitializationFailedException(String.format("Violation store path is not a directory: %s", storeFolder.getAbsolutePath()));
        }

        Path indexPath = storedRulesFile.toPath();
        boolean indexExists = Files.exists(indexPath, LinkOption.NOFOLLOW_LINKS);
        if (!indexExists) {
        if (!indexExists) {
            if (FAIL_INTEGRITY.equals(integrityMode)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot initialize violation store in fail mode because %s is absent", indexPath.toAbsolutePath()));
            }
            if (!storeCreationAllowed) {
                throwStoreCreationDisabled();
            }
            try {
                Files.createFile(indexPath);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
        }

        if (!Files.isRegularFile(indexPath, LinkOption.NOFOLLOW_LINKS)) {
            throw new StoreInitializationFailedException(String.format(
                    "Violation store index %s must be a regular file directly in the store folder", indexPath.toAbsolutePath()));
        }
    }

    private void throwStoreCreationDisabled() {
        throw new StoreInitializationFailedException(String.format(
                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && REPAIR_INTEGRITY.equals(integrityMode)) {
                if (existingFileName != null) {
                    forgetRule(description, existingFileName);
                }
                return;
            }
            if (violations.isEmpty() && REPAIR_INTEGRITY.equals(integrityMode) && existingFileName == null) {
                return;
            }

            String ruleFileName = existingFileName != null ? existingFileName : createRuleFileName(description, false);
            Path ruleFile = validateSaveTarget(description, ruleFileName);
            if (existingFileName == null) {
                writeNew(violations, ruleFile);
                storedRules.putIfAbsent(description, ruleFileName);
            } else {
                writeExisting(violations, ruleFile);
            }
        }
    }

    private void forgetRule(String description, String fileName) {
        EntryPath entryPath = resolveEntryPath(fileName);
        boolean sharedWithAnotherEntry = false;
        for (Map.Entry<String, String> entry : storedRules.entries().entrySet()) {
            if (!description.equals(entry.getKey()) && sameEntryFile(entry.getValue(), entryPath)) {
                sharedWithAnotherEntry = true;
                break;
            }
        }
        if (!sharedWithAnotherEntry && entryPath.isValidFile()) {
            deleteEntryFile(entryPath);
        }
        storedRules.remove(description);
        storedRules.syncFileSystem();
    }

    private boolean sameEntryFile(String fileName, EntryPath reference) {
        if (fileName.equals(reference.recordedName)) {
            return true;
        }
        EntryPath other = resolveEntryPath(fileName);
        return reference.identity != null && reference.identity.equals(other.identity);
    }

    private void writeNew(List<String> violations, Path ruleFile) {
        try {
            Files.write(ruleFile, encodedViolations(violations), StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private void writeExisting(List<String> violations, Path ruleFile) {
        try {
            if (Files.exists(ruleFile, LinkOption.NOFOLLOW_LINKS)) {
                Files.write(ruleFile, encodedViolations(violations), StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
            } else {
                Files.write(ruleFile, encodedViolations(violations), StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
            }
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private byte[] encodedViolations(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        return builder.toString().getBytes(UTF_8);
    }

    private Path validateSaveTarget(String description, String fileName) {
        if (fileName == null || fileName.trim().isEmpty()) {
            throw new StoreUpdateFailedException(String.format("RuleViolationFileNameStrategy returned no name for rule '%s'", description));
        }
        Path target = storeFolder.toPath().toAbsolutePath().normalize().resolve(fileName).normalize();
        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
        if (!isDirectChild(target, folder) || STORED_RULES_FILE_NAME.equals(fileName)) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to store rule '%s' in unsafe violation file '%s'", description, fileName));
        }

        String ownFileName = storedRules.getProperty(description);
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            if (ownFileName == null || !ownFileName.equals(fileName)) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to overwrite existing file '%s' not recorded for rule '%s'", fileName, description));
            }
            EntryPath resolved = resolveEntryPath(fileName);
            if (!resolved.isValidFile()) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to write rule '%s' through unsafe violation file '%s'", description, fileName));
            }
        } else if (ownFileName != null && !ownFileName.equals(fileName)) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to write rule '%s' in a file its entry does not record: '%s'", description, fileName));
        }

        for (Map.Entry<String, String> entry : storedRules.entries().entrySet()) {
            if (!description.equals(entry.getKey()) && target.equals(folder.resolve(entry.getValue()).normalize())) {
                throw new StoreUpdateFailedException(String.format(
                        "Refusing to write rule '%s' in file '%s' recorded by another rule", description, fileName));
            }
        }
        return target;
    }

    private boolean isDirectChild(Path path, Path folder) {
        return path.startsWith(folder) && folder.equals(path.getParent());
    }

    private String createRuleFileName(String description, boolean duringInitialization) {
        String fileName;
        try {
            fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            if (duringInitialization) {
                throw new StoreInitializationFailedException(String.format(
                        "Could not derive a violation file name for rule '%s'", description), e);
            }
            throw e;
        }
        if (fileName == null || fileName.trim().isEmpty()) {
            String message = String.format("RuleViolationFileNameStrategy returned no name for rule '%s'", description);
            if (duringInitialization) {
                throw new StoreInitializationFailedException(message);
            }
            throw new StoreUpdateFailedException(message);
        }
        return fileName;
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storedRules) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            EntryPath entryPath = resolveEntryPath(ruleDetailsFileName);
            if (!entryPath.isValidFile()) {
                throw new StoreReadException(new IOException(String.format(
                        "Stored violation file '%s' is not a regular file directly in the store folder", ruleDetailsFileName)));
            }
            List<String> result = readLines(entryPath.realPath);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(Path ruleDetailsFile) {
        String violationsText = readStoreFile(ruleDetailsFile);
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
                .map(this::unescape)
                .collect(toList());
    }

    private String readStoreFile(Path file) {
        try {
            String result = new String(Files.readAllBytes(file), UTF_8);
            return normalizeStoreLineBreaks(result);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    private String normalizeStoreLineBreaks(String value) {
        return value.replace("\r\n", "\n").replace('\r', '\n');
    }

    private EntryPath resolveEntryPath(String recordedName) {
        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
        Path path = folder.resolve(recordedName == null ? "" : recordedName).normalize();
        EntryPath result = new EntryPath(recordedName, path);
        try {
            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
                return result;
            }
            Path realPath = path.toRealPath();
            result.realPath = realPath;
            result.identity = fileIdentity(realPath);
            Path realFolder = folder.toRealPath();
            Path realIndex = folder.resolve(STORED_RULES_FILE_NAME).toRealPath();
            result.validFile = !realPath.equals(realIndex)
                    && realPath.getParent() != null
                    && realPath.getParent().equals(realFolder)
                    && Files.isRegularFile(realPath);
        } catch (IOException ignored) {
            // A dangling link and an inaccessible path are both broken entries.
        }
        return result;
    }

    private String fileIdentity(Path path) {
        try {
            Object fileKey = Files.readAttributes(path, java.nio.file.attribute.BasicFileAttributes.class).fileKey();
            return fileKey == null ? path.toString() : "key:" + fileKey;
        } catch (IOException ignored) {
            return path.toString();
        }
    }

    private IntegrityAnalysis analyzeIntegrity() {
        List<Entry> entries = new ArrayList<>();
        for (Map.Entry<String, String> property : storedRules.entries().entrySet()) {
            String derivedName = randomFileNames
                    ? property.getValue()
                    : createRuleFileName(property.getKey(), true);
            EntryPath entryPath = resolveEntryPath(property.getValue());
            entries.add(new Entry(property.getKey(), property.getValue(), derivedName, entryPath));
        }

        Map<String, Integer> names = new HashMap<>();
        Map<String, Integer> identities = new HashMap<>();
        for (Entry entry : entries) {
            increment(names, entry.recordedName);
            if (entry.path.identity != null) {
                increment(identities, entry.path.identity);
            }
        }

        Map<String, Integer> derivedNames = new HashMap<>();
        for (Entry entry : entries) {
            increment(derivedNames, entry.derivedName);
        }
        Set<String> recordedPaths = new HashSet<>();
        for (Entry entry : entries) {
            recordedPaths.add(storeFolder.toPath().toAbsolutePath().normalize().resolve(entry.recordedName).normalize().toString());
        }

        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
        for (Entry entry : entries) {
            entry.broken = !entry.path.isValidFile();
            entry.resolved = !entry.broken && readLines(entry.path.realPath).isEmpty();
            entry.shared = names.get(entry.recordedName) > 1
                    || (entry.path.identity != null && identities.get(entry.path.identity) > 1);
            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
            Path derivedPath = folder.resolve(entry.derivedName == null ? "" : entry.derivedName).normalize();
            entry.colliding = derivedNames.get(entry.derivedName) > 1;
            entry.occupied = !isDirectChild(derivedPath, folder)
                    || STORED_RULES_FILE_NAME.equals(entry.derivedName)
                    || (!entry.recordedName.equals(entry.derivedName) && Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS))
                    || recordedByAnotherEntry(entry, entries, derivedPath, recordedPaths);
        }

        List<File> unownedFiles = new ArrayList<>();
        Set<String> ownedIdentities = new HashSet<>();
        Set<String> ownedIdentities = new HashSet<>();
        for (Entry entry : entries) {
            if (entry.path.identity != null) {
                ownedIdentities.add(entry.path.identity);
            }
        }
        File[] files = storeFolder.listFiles();
        if (files != null) {
            for (File file : files) {
                if (!STORED_RULES_FILE_NAME.equals(file.getName())
                        && Files.isRegularFile(file.toPath(), LinkOption.NOFOLLOW_LINKS)) {
                    String identity = fileIdentity(file.toPath());
                    if (!ownedIdentities.contains(identity)) {
                        unownedFiles.add(file);
                    }
                }
            }
        }
        Collections.sort(unownedFiles, Comparator.comparing(File::getName));
        return new IntegrityAnalysis(entries, unownedFiles);
    }

    private boolean recordedByAnotherEntry(Entry entry, List<Entry> entries, Path derivedPath, Set<String> recordedPaths) {
        String derived = derivedPath.toString();
        for (Entry other : entries) {
            if (!entry.description.equals(other.description)) {
                Path otherPath = storeFolder.toPath().toAbsolutePath().normalize().resolve(other.recordedName).normalize();
                if (derived.equals(otherPath.toString())) {
                    return true;
                }
            }
        }
        return recordedPaths.contains(derived) && !derived.equals(storeFolder.toPath().toAbsolutePath().normalize().resolve(entry.recordedName).normalize().toString());
    }

    private void increment(Map<String, Integer> counts, String key) {
        Integer current = counts.get(key);
        counts.put(key, current == null ? 1 : current + 1);
    }

    private void repair(IntegrityAnalysis analysis) {
        boolean indexChanged = false;
        for (Entry entry : analysis.entriesSortedByDescription()) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken || entry.resolved) {
                if (entry.resolved) {
                    deleteEntryFile(entry.path);
                }
                storedRules.remove(entry.description);
                indexChanged = true;
            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                moveEntry(entry);
                storedRules.setProperty(entry.description, entry.derivedName);
                indexChanged = true;
            }
        }
        if (indexChanged) {
            storedRules.syncFileSystem();
        }
    }

    private void moveEntry(Entry entry) {
        Path destination = storeFolder.toPath().toAbsolutePath().normalize().resolve(entry.derivedName).normalize();
        try {
            Files.move(entry.path.realPath, destination);
            if (!entry.path.realPath.equals(entry.path.lexicalPath)) {
                Files.deleteIfExists(entry.path.lexicalPath);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
        }
    }

    private void deleteEntryFile(EntryPath entryPath) {
        try {
            if (entryPath.realPath != null) {
                Files.deleteIfExists(entryPath.realPath);
            }
            if (entryPath.lexicalPath != null && !entryPath.lexicalPath.equals(entryPath.realPath)) {
                Files.deleteIfExists(entryPath.lexicalPath);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not delete violation file '%s'", entryPath.recordedName), e);
        }
    }

    /** A path as recorded in the index and the file it resolves to. */
    private static class EntryPath {
        private final String recordedName;
        private final Path lexicalPath;
        private Path realPath;
        private String identity;
        private boolean validFile;

        EntryPath(String recordedName, Path lexicalPath) {
            this.recordedName = recordedName;
            this.lexicalPath = lexicalPath;
        }

        boolean isValidFile() {
            return validFile;
        }
    }

    private static class Entry {
        private final String description;
        private final String recordedName;
        private final String derivedName;
        private final EntryPath path;
        private boolean broken;
        private boolean resolved;
        private boolean shared;
        private boolean misplaced;
        private boolean colliding;
        private boolean occupied;

        Entry(String description, String recordedName, String derivedName, EntryPath path) {
            this.description = description;
            this.recordedName = recordedName;
            this.derivedName = derivedName;
            this.path = path;
        }

        String detail() {
            List<String> details = new ArrayList<>();
            if (broken) details.add("broken");
            if (resolved) details.add("resolved");
            if (shared) details.add("shared");
            if (misplaced) details.add("misplaced");
            if (colliding) details.add("colliding");
            if (occupied) details.add("occupied");
            return String.format("%s [recorded=%s, derived=%s; %s]", description, recordedName, derivedName, String.join(", ", details));
        }
    }

    private static class IntegrityAnalysis {
        private final List<Entry> entries;
        private final List<File> unownedFiles;

        IntegrityAnalysis(List<Entry> entries, List<File> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        boolean hasProblems() {
            for (Entry entry : entries) {
                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
                    return true;
                }
            }
            return !unownedFiles.isEmpty();
        }

        String failureMessage(File index) {
            StringBuilder result = new StringBuilder();
            result.append("Violation store integrity check failed for ").append(index.getAbsolutePath()).append(":");
            appendEntries(result, "broken", entry -> entry.broken && !entry.shared);
            appendEntries(result, "resolved", entry -> entry.resolved && !entry.shared && !entry.broken);
            appendEntries(result, "shared", entry -> entry.shared);
            appendEntries(result, "misplaced/colliding/occupied", entry ->
                    !entry.shared && !entry.broken && !entry.resolved && (entry.misplaced || entry.colliding || entry.occupied));
            if (!unownedFiles.isEmpty()) {
                result.append("\n  unowned:");
                for (File file : unownedFiles) {
                    result.append("\n    ").append(file.getName());
                }
            }
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String condition, EntryPredicate predicate) {
            List<Entry> matching = entries.stream().filter(predicate::test).sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
            if (!matching.isEmpty()) {
                result.append("\n  ").append(condition).append(":");
                for (Entry entry : matching) {
                    result.append("\n    ").append(entry.detail());
                }
            }
        }

